begin;
-- Count rejected operations in the outer transaction; roll back only their writes.
create or replace function public.portal_command(operation text,payload jsonb default '{}') returns jsonb language plpgsql security definer set search_path='' as $$declare actor uuid:=private.require_actor();rid uuid;request public.organizer_requests;begin
 perform private.consume_limit(operation);
 begin
 if operation='request_organizer' then insert into public.organizer_requests(user_id,reason) values(actor,payload->>'reason') returning id into rid;return jsonb_build_object('id',rid);
 elsif operation='review_organizer' then if not private.has_role('admin') then raise exception 'Admin required';end if;select * into strict request from public.organizer_requests where id=(payload->>'id')::uuid and status='pending' for update;
 if request.user_id=actor then raise exception 'Cannot approve own request';end if;if char_length(btrim(coalesce(payload->>'note','')))<10 then raise exception 'Review note required';end if;
 if (payload->>'approve')::boolean then perform public.portal_command_core('role_set',jsonb_build_object('user_id',request.user_id,'role','organizer','enabled',true));end if;
 update public.organizer_requests set status=case when(payload->>'approve')::boolean then 'approved' else 'rejected' end,reviewed_by=actor,review_note=payload->>'note',reviewed_at=now() where id=request.id;perform private.audit(operation,request.id);return '{}';
 elsif operation='support_report' then insert into public.support_issues(user_id,subject,description) values(actor,payload->>'subject',payload->>'description') returning id into rid;return jsonb_build_object('id',rid);
 elsif operation='support_resolve' then if not private.has_role('admin') then raise exception 'Admin required';end if;if char_length(btrim(coalesce(payload->>'resolution','')))<10 then raise exception 'Resolution note required';end if;update public.support_issues set status='resolved',resolution=payload->>'resolution',reviewed_by=actor where id=(payload->>'id')::uuid;perform private.audit(operation,(payload->>'id')::uuid);return '{}';
 elsif operation='template_deactivate' then if not private.has_role('admin') then raise exception 'Admin required';end if;update public.certificate_templates set active=false where id=(payload->>'id')::uuid;if not found then raise exception 'Template not found';end if;perform private.audit(operation,(payload->>'id')::uuid);return '{}';
 else return public.portal_command_core(operation,payload);end if;
 exception when others then return jsonb_build_object('error',sqlerrm,'code',sqlstate);end;
 end;$$;
create or replace function public.portal_read_core(resource text,args jsonb default '{}') returns jsonb language plpgsql stable security definer set search_path='' as $$
declare actor uuid:=private.require_actor();eid uuid:=nullif(args->>'event_id','')::uuid;page_no integer:=greatest(0,least(coalesce((args->>'page')::integer,0),100000));result jsonb;is_admin boolean:=private.has_role('admin');begin
 if resource='managed_events' then select coalesce(jsonb_agg(to_jsonb(q)),'[]') into result from(select e.*,public.event_state(e) effective_status,(select count(*) from public.registrations r where r.event_id=e.id and r.status='confirmed') registered_count from public.events e where private.can_manage(e.id) and (eid is null or eid=e.id) order by created_at desc limit 20 offset page_no*20) q;
 elsif resource='sessions' then perform private.require_manager(eid);select coalesce(jsonb_agg(to_jsonb(s) order by display_order,starts_at),'[]') into result from public.event_sessions s where event_id=eid;
 elsif resource='registrations' then select coalesce(jsonb_agg(to_jsonb(q)),'[]') into result from(select r.*,e.title event_title,e.starts_at,e.ends_at,e.venue,e.status event_status,e.certificate_enabled,e.feedback_requires_attendance,e.cancellation_closes_at,private.attendance_percent(r.id) attendance_percent from public.registrations r join public.events e on e.id=r.event_id where r.user_id=actor and (not coalesce((args->>'upcoming')::boolean,false) or (r.status='confirmed' and e.starts_at>now() and e.status<>'cancelled')) and (not(args?'id') or r.id=(args->>'id')::uuid) order by case when coalesce((args->>'upcoming')::boolean,false) then e.starts_at end asc,r.created_at desc limit 20 offset page_no*20) q;
 elsif resource='participants' then perform private.require_manager(eid);select coalesce(jsonb_agg(to_jsonb(q)),'[]') into result from(select r.id,r.reference,r.status,r.created_at,r.team_id,r.user_id,p.full_name,p.rrn,p.department,p.study_year,p.email,private.attendance_percent(r.id) attendance_percent from public.registrations r join public.profiles p on p.id=r.user_id where r.event_id=eid and (coalesce(args->>'search','')='' or concat_ws(' ',p.full_name,p.rrn,p.department,r.reference) ilike '%'||(args->>'search')||'%') and (coalesce(args->>'status','')='' or r.status=args->>'status') and (coalesce(args->>'attendance','')='' or (case when private.attendance_percent(r.id)>0 then 'present' else 'absent' end)=args->>'attendance') order by r.created_at,r.id limit 50 offset page_no*50) q;
 elsif resource='notifications' then select coalesce(jsonb_agg(to_jsonb(q)),'[]') into result from(select * from public.notifications where user_id=actor order by created_at desc limit 20 offset page_no*20) q;
 elsif resource='teams' then select coalesce(jsonb_agg(to_jsonb(q)),'[]') into result from(select t.*,(select jsonb_agg(jsonb_build_object('user_id',m.user_id,'name',p.full_name,'status',m.status)) from public.team_members m join public.profiles p on p.id=m.user_id where m.team_id=t.id) members from public.teams t where exists(select 1 from public.team_members where team_id=t.id and user_id=actor) and (eid is null or t.event_id=eid) order by t.created_at desc limit 20 offset page_no*20) q;
 elsif resource='attendance' then if eid is not null then perform private.require_manager(eid);end if;select coalesce(jsonb_agg(to_jsonb(q)),'[]') into result from(select a.*,p.full_name,r.reference,s.title session_title,e.title event_title from public.attendance a join public.registrations r on r.id=a.registration_id join public.profiles p on p.id=r.user_id join public.events e on e.id=a.event_id left join public.event_sessions s on s.id=a.session_id where (eid is not null and a.event_id=eid) or (eid is null and r.user_id=actor) order by a.checked_in_at desc limit 50 offset page_no*50) q;
 elsif resource='attendance_corrections' then perform private.require_manager(eid);select coalesce(jsonb_agg(to_jsonb(q)),'[]') into result from(select c.* from public.attendance_corrections c join public.attendance a on a.id=c.attendance_id where a.event_id=eid order by c.created_at desc limit 50 offset page_no*50) q;
 elsif resource='certificates' then if eid is not null then perform private.require_manager(eid);end if;select coalesce(jsonb_agg(to_jsonb(q)),'[]') into result from(select c.* from public.certificates c where (eid is not null and c.event_id=eid) or(eid is null and c.user_id=actor) order by c.created_at desc limit 20 offset page_no*20) q;
 elsif resource='templates' then if not (is_admin or private.has_role('organizer')) then raise exception 'Staff access required';end if;select coalesce(jsonb_agg(to_jsonb(t)),'[]') into result from public.certificate_templates t where active;
 elsif resource='feedback' then if eid is not null then perform private.require_manager(eid);end if;select coalesce(jsonb_agg(to_jsonb(q)),'[]') into result from(select f.* from public.event_feedback f where (eid is not null and f.event_id=eid) or(eid is null and f.user_id=actor) order by f.created_at desc limit 50 offset page_no*50) q;
 elsif resource='users' then if not is_admin then raise exception 'Admin required';end if;select coalesce(jsonb_agg(to_jsonb(q)),'[]') into result from(select p.*,(select jsonb_agg(role) from public.user_roles where user_id=p.id) roles,(u.email_confirmed_at is not null) email_verified from public.profiles p join auth.users u on u.id=p.id where coalesce(args->>'search','')='' or concat_ws(' ',p.full_name,p.rrn,p.email,p.department) ilike '%'||(args->>'search')||'%' order by p.created_at desc limit 50 offset page_no*50)q;
 elsif resource='categories' then if not is_admin then raise exception 'Admin required';end if;select coalesce(jsonb_agg(to_jsonb(c) order by name),'[]') into result from public.event_categories c;
 elsif resource='audit' then if not is_admin then raise exception 'Admin required';end if;select coalesce(jsonb_agg(to_jsonb(q)),'[]') into result from(select * from public.audit_logs order by created_at desc,id desc limit 50 offset page_no*50) q;
 elsif resource='outbox' then if not is_admin then raise exception 'Admin required';end if;select coalesce(jsonb_agg(to_jsonb(q)),'[]') into result from(select id,status,retry_count,last_error,created_at,delivered_at from public.email_outbox order by created_at desc limit 50 offset page_no*50)q;
 elsif resource='settings' then if not is_admin then raise exception 'Admin required';end if;select coalesce(jsonb_agg(to_jsonb(s)),'[]') into result from public.platform_settings s;
 elsif resource='roster' then if not is_admin then raise exception 'Admin required';end if;select coalesce(jsonb_agg(to_jsonb(q)),'[]') into result from(select * from public.student_roster order by updated_at desc limit 50 offset page_no*50)q;
 elsif resource='stats' then
 if args->>'scope'='admin' and not is_admin then raise exception 'Admin required';end if;
 if args->>'scope'='organizer' and not(private.has_role('organizer') or is_admin) then raise exception 'Organizer required';end if;
 return jsonb_build_object('events',(select count(*) from public.events where case when args->>'scope'='admin' then true when args->>'scope'='organizer' then private.can_manage(id) else status<>'draft' end),
 'registrations',(select count(*) from public.registrations r where r.status='confirmed' and case when args->>'scope'='admin' then true when args->>'scope'='organizer' then private.can_manage(r.event_id) else r.user_id=actor end),
 'certificates',(select count(*) from public.certificates c where c.status='issued' and case when args->>'scope'='admin' then true when args->>'scope'='organizer' then private.can_manage(c.event_id) else c.user_id=actor end),
 'attendance',(select count(distinct a.registration_id) from public.attendance a join public.registrations r on r.id=a.registration_id where a.present and r.status='confirmed' and case when args->>'scope'='admin' then true when args->>'scope'='organizer' then private.can_manage(a.event_id) else r.user_id=actor end),
 'users',case when is_admin and args->>'scope'='admin' then (select count(*) from public.profiles) end,
 'active_students',case when is_admin and args->>'scope'='admin' then(select count(*) from public.profiles p join public.user_roles r on r.user_id=p.id where p.is_active and r.role='student') end,
 'available_seats',case when args->>'scope' in('organizer','admin') then(select coalesce(sum(greatest(0,e.capacity-(select count(*) from public.registrations r where r.event_id=e.id and r.status='confirmed'))),0) from public.events e where (args->>'scope'='admin' or private.can_manage(e.id)) and e.status='published') end,
 'published_events',(select count(*) from public.events e where e.status='published' and (args->>'scope' not in('admin','organizer') or args->>'scope'='admin' or private.can_manage(e.id))),
 'upcoming_registrations',(select count(*) from public.registrations r join public.events e on e.id=r.event_id where r.user_id=actor and r.status='confirmed' and e.starts_at>now()),
 'pending_certificates',case when args->>'scope' in('organizer','admin') then(select count(*) from public.certificates c where c.status='pending' and (args->>'scope'='admin' or private.can_manage(c.event_id))) end);
 elsif resource='reports' then if eid is not null then perform private.require_manager(eid);elsif not(is_admin or private.has_role('organizer')) then raise exception 'Staff reports required';end if;
 return jsonb_build_object(
 'events',coalesce((select jsonb_agg(to_jsonb(q)) from(select e.id,e.title,e.status,e.capacity,(select count(*) from public.registrations r where r.event_id=e.id and r.status='confirmed') registrations,(select count(distinct a.registration_id) from public.attendance a join public.registrations r on r.id=a.registration_id where a.event_id=e.id and a.present and r.status='confirmed') present,(select count(*) from public.certificates where event_id=e.id and status='issued') certificates,(select round(avg(overall),2) from public.event_feedback where event_id=e.id) rating from public.events e where private.can_manage(e.id) and(eid is null or e.id=eid) order by e.starts_at desc limit 50 offset page_no*50)q),'[]'),
 'departments',coalesce((select jsonb_agg(to_jsonb(q)) from(select p.department,count(*) registrations from public.registrations r join public.profiles p on p.id=r.user_id where r.status='confirmed' and private.can_manage(r.event_id) and(eid is null or r.event_id=eid) group by p.department order by count(*) desc limit 100)q),'[]'),
 'trends',coalesce((select jsonb_agg(to_jsonb(q) order by q.day) from(select (r.created_at at time zone 'Asia/Kolkata')::date as "day",count(*) registrations from public.registrations r where r.created_at>now()-interval '30 days' and private.can_manage(r.event_id) and(eid is null or r.event_id=eid) group by 1)q),'[]'),
 'categories',coalesce((select jsonb_agg(to_jsonb(q)) from(select c.name,count(*) events from public.events e join public.event_categories c on c.id=e.category_id where private.can_manage(e.id) and(eid is null or e.id=eid) group by c.name)q),'[]'),
 'feedback',coalesce((select jsonb_agg(to_jsonb(q)) from(select overall rating,count(*) responses from public.event_feedback f where private.can_manage(f.event_id) and(eid is null or f.event_id=eid) group by overall order by overall)q),'[]'));
 else raise exception 'Unknown private resource';end if;return result;
end;$$;
create or replace function public.portal_read(resource text,args jsonb default '{}') returns jsonb language plpgsql stable security definer set search_path='' as $$declare actor uuid:=private.require_actor();result jsonb;page_no integer:=greatest(0,least(coalesce((args->>'page')::integer,0),100000));begin
 if resource='notification_count' then return to_jsonb((select count(*) from public.notifications where user_id=actor and read_at is null));
 elsif resource='organizer_requests' then select coalesce(jsonb_agg(to_jsonb(q)),'[]') into result from(select r.*,p.full_name,p.email from public.organizer_requests r join public.profiles p on p.id=r.user_id where(private.has_role('admin') or r.user_id=actor) order by r.created_at desc limit 50 offset page_no*50)q;return result;
 elsif resource='support_issues' then select coalesce(jsonb_agg(to_jsonb(q)),'[]') into result from(select * from public.support_issues where private.has_role('admin') or user_id=actor order by created_at desc limit 50 offset page_no*50)q;return result;
 else return public.portal_read_core(resource,args);end if;end;$$;
create or replace function public.claim_email_jobs() returns jsonb language plpgsql security definer set search_path='' as $$declare result jsonb;begin
 update public.email_outbox set status='failed',last_error='Retry window exhausted; manual review required' where status in('pending','processing') and (created_at<now()-interval '23 hours' or retry_count>=8) and(lease_until is null or lease_until<now());
 with jobs as(select id from public.email_outbox where retry_count<8 and created_at>=now()-interval '23 hours' and((status='pending' and next_attempt_at<=now())or(status='processing' and lease_until<now())) order by created_at for update skip locked limit 5), claimed as(update public.email_outbox j set status='processing',retry_count=j.retry_count+1,lease_until=now()+interval '5 minutes',lease_token=gen_random_uuid() from jobs where j.id=jobs.id returning j.*) select coalesce(jsonb_agg(to_jsonb(claimed)),'[]') into result from claimed;return result;end;$$;
drop function public.complete_certificate(uuid,text);
create function public.complete_certificate(certificate_id uuid,storage_path text,document_issued_at timestamptz default now()) returns void language plpgsql security definer set search_path='' as $$declare c public.certificates;e public.events;begin
 select event_id into strict e.id from public.certificates where id=certificate_id;select * into strict e from public.events where id=e.id for update;select * into strict c from public.certificates where id=certificate_id for update;
 if document_issued_at>now()+interval '1 minute' or document_issued_at<now()-interval '15 minutes' then raise exception 'Certificate document timestamp is stale';end if;
 if storage_path<>c.user_id::text||'/'||c.id::text||'.pdf' then raise exception 'Invalid private certificate path';end if;
 if c.status='issued' and c.object_path=storage_path then return;end if;
 if c.status<>'pending' or e.status<>'completed' or not e.attendance_finalized or private.attendance_percent(c.registration_id)<e.certificate_attendance_percent or not exists(select 1 from public.registrations where id=c.registration_id and status='confirmed') then raise exception 'Certificate finalization denied';end if;
 update public.certificates set object_path=storage_path,status='issued',issued_at=document_issued_at where id=c.id;perform private.audit('certificate.issued',c.id,jsonb_build_object('approved_by',c.approved_by));perform private.notify(c.user_id,c.event_id,'Certificate available','Your approved certificate is ready to download.','certificate:'||c.id);end;$$;
revoke all on function public.complete_certificate(uuid,text,timestamptz) from public,anon,authenticated;grant execute on function public.complete_certificate(uuid,text,timestamptz) to service_role;
commit;
